import{_ as i,h as r,i as a,c as d,v as o,p as n,x as l,m as s,e as E,S as c}from"./chunks/framework.Dvtg8yj2.js";const k=JSON.parse('{"title":"超节点内 MoE 专家并行与分布式 KV","description":"","frontmatter":{"title":"超节点内 MoE 专家并行与分布式 KV","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cloudmatrix-moe-kv.md","filePath":"llm/cloudmatrix-moe-kv.md","lastUpdated":1788454257000}'),p={name:"llm/cloudmatrix-moe-kv.md"};function h(m,e,P,B,D,A){const t=r("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="超节点内-moe-专家并行与分布式-kv" tabindex="-1">超节点内 MoE 专家并行与分布式 KV <a class="header-anchor" href="#超节点内-moe-专家并行与分布式-kv" aria-label="Permalink to &quot;超节点内 MoE 专家并行与分布式 KV&quot;">​</a></h1><div class="epigraph"><p>超节点的带宽若够把 All-to-All 留在域内，专家就可以一 Die 一份地铺开，KV 也可以从「跟请求绑在某张卡上」变成池里可对等读取的页。</p><footer>—— 对照 CloudMatrix-Infer 在 CloudMatrix384 上对大规模专家并行（如 EP320）与分离式缓存池的设计</footer></div><p>MoE 推理有两笔跨设备账单：token 去找专家的 dispatch/combine，以及注意力要读的历史 KV。<a href="/llm/infer-ep">专家并行推理</a> 在普通以太网集群里常被 decode 的小 payload 打死，KV 则习惯跟 decode 卡绑死，调度变成「请求必须去有它缓存的那台」。CloudMatrix384 的 UB 域把这两笔账单收进同一超节点：论文中的大规模专家并行可以把 DeepSeek-R1 铺到 EP320——每张 910C 双 Die，一 Die 一个路由专家——同时把 KV 放进经 UB 均匀可达的分布式缓存池。本篇只写超节点<strong>内部</strong>这两件事如何咬合，跨超节点走 RoCE 见 <a href="/llm/cloudmatrix-roce-scaleout">下一篇</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>671B 级 MoE 的专家权重放不进单卡，decode 又每步只产几个 token。EP 度小，则每 rank 串行跑多个专家，延迟叠在同一 Die 上；EP 度大，则 All-to-All 的对端数膨胀，普通 RoCE 集群的启动延迟会盖过 grouped GEMM。另一侧，长上下文与多会话把 KV 容量推到单卡 HBM 之外。若 KV 必须本地，调度就退化成缓存亲和：prefill 写在哪，decode 就只能在哪，弹性与装箱都僵。</p><p>超节点要同时解这两件事，前提是域内任意 NPU 对之间的通信不再经过数据中心叶子。否则「超节点」只是把 8 卡箱堆密了，编程模型仍是跨机 EP 加本地 KV。</p><h3 id="专家并行与-kv-不是同一条通信" tabindex="-1">专家并行与 KV 不是同一条通信 <a class="header-anchor" href="#专家并行与-kv-不是同一条通信" aria-label="Permalink to &quot;专家并行与 KV 不是同一条通信&quot;">​</a></h3><p>Dispatch/combine 是消息语义：按路由表把 token 向量送到持有该专家的 Die，再把输出送回家，语义是置换不是求和。KV 访问更接近内存语义：注意力核要的是逻辑位置 \\(t\\) 上的 \\(k_t,v_t\\)，它们可以住在本卡分页池，也可以住在 UB 另一端的 DRAM/HBM 页。把 KV 误做成每步 All-to-All 会把带宽打爆；把专家输出误做成远程 load 又会失去集合通信的流控。两者共享互连，不共享原语。</p><p><span class="marginnote">DeepSeek-R1 公开结构是每层 256 个路由专家加共享专家。EP320 一类配置用冗余专家做负载均衡，使「一 Die 一专家」在有热专家时仍可调度，而不是把 256 与 320 当成同一数字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>域内 EP 的目标是让 decode 的 MoE 段不再在同一 rank 上串行堆专家。CloudMatrix-Infer 的做法是宽 EP：decode 实例可以把专家铺到数百 Die，每 Die 常驻一份专家权重与对应 grouped GEMM。路由仍在本地完成，dispatch/combine 走 UB。因为节点间带宽相对节点内衰减不到 3%，EP 组不必裁在 8 卡边界上——这正是 <a href="/llm/rack-as-accelerator">机柜作为逻辑加速器</a> 在昇腾侧的对应物。</p><p>Prefill 与 decode 可以选不同 EP 度。论文里 prefill 实例示例为 16 张 910C（32 Die）上 EP32，每 rank 多个专家以喂饱算力；decode 追求低 TPOT 时把 EP 拉宽。两阶段之间的 KV 不跟某一张生成卡死绑，而是写入第三池：缓存子系统。P 侧写完页，D 侧按全局句柄读，带宽由 UB 提供均匀访问，从而调度不必先问「这块 KV 现在在哪张物理卡」。</p>',12)),(a(),n(c,null,{default:l(()=>[E(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E6%9C%AC%E6%AD%A5%20token%22%5D%20--%3E%20RTE%5B%22%E6%9C%AC%E5%9C%B0%E8%B7%AF%E7%94%B1%22%5D%0A%20%20RTE%20--%3E%20DSP%5B%22%E5%9F%9F%E5%86%85%20dispatch%22%5D%0A%20%20DSP%20--%3E%20EXP%5B%22%E4%B8%80%20Die%20%E4%B8%80%E4%B8%93%E5%AE%B6%20GEMM%22%5D%0A%20%20EXP%20--%3E%20CMB%5B%22combine%20%E5%9B%9E%E5%AE%B6%22%5D%0A%20%20CMB%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%AF%BB%20KV%22%5D%0A%20%20POOL%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%20KV%20%E6%B1%A0%22%5D%20--%3E%7C%22UB%20%E5%AF%B9%E7%AD%89%E8%AF%BB%22%7C%20ATT%0A%20%20PRE%5B%22Prefill%20%E5%86%99%E9%A1%B5%22%5D%20--%3E%20POOL%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="分布式-kv-是池-不是副本附属物" tabindex="-1">分布式 KV 是池，不是副本附属物 <a class="header-anchor" href="#分布式-kv-是池-不是副本附属物" aria-label="Permalink to &quot;分布式 KV 是池，不是副本附属物&quot;">​</a></h3><p>方法上把缓存做成独立可伸缩的子系统：CPU DRAM 聚合进内存池，NPU 经 UB 直接访问，命中不必把整段 KV 先搬回「主 decode 卡」再算。这与 KV-centric 架构相反——后者调度围着块所在 GPU 转。对等池把局部性从正确性条件降级为性能提示：近端更快，远端仍正确。前缀复用、多轮对话、抢占后恢复，都可以按页句柄在池里完成，而不强制会话粘在同一 Pod。</p><p><span class="marginnote">均匀可达不等于零代价。页仍应尽量放在即将做 decode 的 Die 近处；池解决的是「能不能读」，不是「该不该每步远程扫整层」。带宽不等式与 <a href="/llm/kv-offload">卸载</a> 相同，只是 \\(B_{\\mathrm{io}}\\) 换成 UB。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>宽 EP 能降 decode 延迟，是因为专家计算从「一卡串行 \\(n\\) 个专家」变成「\\(n\\) 个 Die 并行各一个」。通信体积仍随 token 数与隐藏维走，但超节点把这笔通信的屋顶线抬到接近节点内。负载不均时热专家 Die 仍决定迭代时间，所以需要冗余专家与 <a href="/llm/moe-load-balance">负载均衡</a>；硬件带宽不能消除路由倾斜。</p><p>分布式 KV 能成立，是因为注意力只关心逻辑位置上的键值，不关心页在哪张卡的物理地址，这与 <a href="/llm/paged-attention">PagedAttention</a> 一致。超节点多的是一层：页表的后端可以是本卡 HBM，也可以是池里另一节点的 DRAM。译址在运行时完成。PD 分离时，P 实例不必与 D 实例共享 PCIe 域，只要共享池的句柄空间；这比跨机拷贝整段连续 KV 更接近「一块加速器上的两个队列」，见 <a href="/llm/pd-disaggregation">PD 分离</a>。</p><h3 id="两套并行不要抢同一条队列" tabindex="-1">两套并行不要抢同一条队列 <a class="header-anchor" href="#两套并行不要抢同一条队列" aria-label="Permalink to &quot;两套并行不要抢同一条队列&quot;">​</a></h3><p>MoE All-to-All 与 KV 远程读若挤在同一无区分队列，decode 的 TPOT 会被大块 KV 预取戳出尖刺。工程上应对 UB 上的集合通信与内存语义流量做优先级或平面划分。专家权重常驻近端 HBM，KV 冷页才下沉 DRAM 池；不要把专家也「分布式」到每步远程取，那会把 MoE 变成带宽灾难。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>超节点内的宽 EP 有爆炸半径：数百 Die 构成一份 decode 副本，单 Die 故障或一条 UB 链路降级，影响的是整份 MoE，而不是少一个副本。维护窗口按超节点设计。EP320 是 DeepSeek-R1 在该硬件上的一种工作点，不是所有 MoE 的默认；Mixtral 8 专家通常复制比宽 EP 更划算。</p><p>KV 池不能替代量化与淘汰。池扩大的是容量，每 token 字节仍由 GQA/MLA/INT8 决定。跨超节点的会话迁移、多机房副本，必须落到 RoCE 平面，不能假装 UB 域无限大。评测要分开报：域内 EP 的 decode TPOT、池命中时的远程读延迟、以及故意打冷页时的下界，混在一个「tokens/s」里无法复现。</p><p><span class="marginnote">出处中的 6688 tokens/s/NPU prefill、1943 tokens/s/NPU decode（TPOT&lt;50 ms）是论文在 DeepSeek-R1、指定长度与量化下的测量，不是本博客的复现，也不应抄成机房承诺。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>超节点内用 UB 做宽 EP，使 decode 可以接近一 Die 一专家，避免单 rank 串行堆专家。</li><li>KV 做成对等可达的分布式池，调度与数据局部性解耦；P/D/缓存三池独立伸缩。</li><li>Dispatch/combine 走消息语义，KV 走内存语义，两者共享互连但不共用原语。</li><li>热专家倾斜、远程扫层、故障域变大，都是宽 EP + 池化的真实边界。</li><li>跨超节点仍走 Scale-Out，不能把 UB 故事写到机房之间。</li><li>出处：Zuo et al., <em>Serving Large Language Models on Huawei CloudMatrix384</em>, arXiv:2506.12708；并行语义对照 GShard / DeepSeek 开源部署。</li></ul>',14))])}const f=i(p,[["render",h]]);export{k as __pageData,f as default};
